use std::fs

trait Pricing {
    fn total(self, qty: int, unit: int) -> int
}

struct Plain {}
struct Bulk {}
struct Member {}

impl Pricing for Plain {
    fn total(self, qty: int, unit: int) -> int {
        qty * unit
    }
}

impl Pricing for Bulk {
    fn total(self, qty: int, unit: int) -> int {
        let g = qty * unit
        if qty >= 10 { g - g * 10 / 100 } else { g }
    }
}

impl Pricing for Member {
    fn total(self, qty: int, unit: int) -> int {
        let g = qty * unit
        let mut t = g - g * 5 / 100
        if qty >= 3 { t = t - 100 }
        if t < 0 { 0 } else { t }
    }
}

fn money(c: int) -> string {
    let d = c / 100
    let r = c % 100
    let dollar = "$"
    if r < 10 { dollar + "${d}.0${r}" } else { dollar + "${d}.${r}" }
}

fn calc<P: Pricing>(p: P, qty: int, unit: int) -> int {
    p.total(qty, unit)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut sum = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 4 { continue }
        let name = parts[0]
        let qty: int = parts[1].parse().unwrap_or(0)
        let unit: int = parts[2].parse().unwrap_or(0)
        let kind = parts[3]
        let mut t = 0
        if kind == "plain" {
            t = calc(Plain {}, qty, unit)
        } else if kind == "bulk" {
            t = calc(Bulk {}, qty, unit)
        } else if kind == "member" {
            t = calc(Member {}, qty, unit)
        } else {
            println("${name} invalid kind")
            continue
        }
        sum += t
        println("${name} ${money(t)}")
    }
    println("total ${money(sum)}")
}

